#!/usr/bin/env python
import csv
import json
import os
import sys

from pyscipopt import Model, quicksum

BASE = "/app"
DATA = os.path.join(BASE, "data")
SUB = os.path.join(BASE, "submissions")
os.makedirs(SUB, exist_ok=True)

# ---------------- Read data ----------------
with open(os.path.join(DATA, "config.json")) as f:
    cfg = json.load(f)
DAYS = list(range(1, cfg["planning_days"] + 1))
COVISIT_SAVING = cfg["co_visit_setup_saving_hours"]

vessels = {}
with open(os.path.join(DATA, "vessels.csv")) as f:
    for row in csv.DictReader(f):
        vessels[row["vessel_id"]] = {
            "berths": int(row["technician_berths"]),
            "deck": int(row["deck_spare_units"]),
            "fatigue": int(row["two_day_fatigue_limit"]),
        }

turbines = {}
with open(os.path.join(DATA, "turbines.csv")) as f:
    for row in csv.DictReader(f):
        turbines[row["turbine_id"]] = row["string_id"]

patterns = []
with open(os.path.join(DATA, "route_patterns.csv")) as f:
    for row in csv.DictReader(f):
        patterns.append({
            "id": row["pattern_id"],
            "day": int(row["day"]),
            "vessel": row["vessel_id"],
            "turbines": [t for t in row["covered_turbines"].split(";") if t],
            "hours": float(row["work_hour_capacity"]),
            "cost": float(row["route_cost"]),
            "capability": row["capability"],
            "access": int(row["access_score"]),
            "fatigue": int(row["fatigue_units"]),
        })
pat_by_id = {p["id"]: p for p in patterns}

sail_limits = {}
with open(os.path.join(DATA, "vessel_sailing_limits.csv")) as f:
    for row in csv.DictReader(f):
        sail_limits[row["vessel_id"]] = int(row["max_sailing_days"])

turnaround = []
with open(os.path.join(DATA, "route_turnaround_rules.csv")) as f:
    for row in csv.DictReader(f):
        turnaround.append((row["previous_pattern_id"], row["next_pattern_id"]))

spare_inv = {}
with open(os.path.join(DATA, "spare_inventory.csv")) as f:
    for row in csv.DictReader(f):
        spare_inv[(int(row["day"]), row["spare_type"])] = int(row["available_units"])

tech_pool = {}
with open(os.path.join(DATA, "technician_pool.csv")) as f:
    for row in csv.DictReader(f):
        tech_pool[(int(row["day"]), row["skill"])] = {
            "reg": float(row["regular_hours"]),
            "ot": float(row["overtime_hours"]),
            "cost": float(row["overtime_cost_per_hour"]),
        }

string_limits = {}
with open(os.path.join(DATA, "string_daily_limits.csv")) as f:
    for row in csv.DictReader(f):
        string_limits[row["string_id"]] = {
            "mand": int(row["max_mandatory_tasks_per_day"]),
            "total": int(row["max_total_tasks_per_day"]),
        }

string_rules = []
with open(os.path.join(DATA, "string_opportunity_rules.csv")) as f:
    for row in csv.DictReader(f):
        string_rules.append({
            "id": row["rule_id"],
            "anchor": row["anchor_task_id"],
            "string": row["string_id"],
            "types": [t for t in row["eligible_task_types"].split(";") if t],
            "credit": float(row["credit_per_task"]),
            "max": int(row["max_credit_tasks"]),
        })

CAP_RANK = {"standard": 1, "cable": 2}
tasks = []
with open(os.path.join(DATA, "work_orders.csv")) as f:
    for row in csv.DictReader(f):
        tasks.append({
            "id": row["task_id"],
            "turbine": row["turbine_id"],
            "type": row["task_type"],
            "skill": row["skill"],
            "mandatory": row["mandatory"].strip().lower() == "yes",
            "earliest": int(row["earliest_day"]),
            "due": int(row["due_day"]),
            "latest": int(row["latest_day"]),
            "hours": float(row["duration_hours"]),
            "techs": int(row["technicians_required"]),
            "spare_type": row["spare_type"],
            "spare_units": int(row["spare_units"]),
            "cap": row["required_capability"],
            "access": int(row["min_access_score"]),
            "lateness": float(row["lateness_penalty_per_day"]),
            "downtime": float(row["downtime_cost_per_day"]),
            "deferral": float(row["deferral_penalty"]),
            "credit": float(row["opportunity_credit"]),
        })
task_by_id = {t["id"]: t for t in tasks}
MANDATORY_TYPES = {"corrective", "cable", "compliance"}

# ---------------- Feasible (task, pattern) pairs ----------------
def feasible(t, p):
    if not (t["earliest"] <= p["day"] <= t["latest"]):
        return False
    if t["turbine"] not in p["turbines"]:
        return False
    if CAP_RANK[p["capability"]] < CAP_RANK[t["cap"]]:
        return False
    if p["access"] < t["access"]:
        return False
    return True

tp_pairs = []
for t in tasks:
    for p in patterns:
        if feasible(t, p):
            tp_pairs.append((t["id"], p["id"]))
tp_set = set(tp_pairs)

# ---------------- Build model ----------------
model = Model("offshore_wind_maintenance")
model.setParam("gaprel", 0.0005)
time_limit = 300.0
env_limit = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
if env_limit is not None:
    try:
        time_limit = min(time_limit, float(env_limit))
    except ValueError:
        pass
model.setParam("limits/time", time_limit)

x = {}
for p in patterns:
    x[p["id"]] = model.addVar(name=f"x_{p['id']}", vtype="B", lb=0, ub=1, obj=0.0)

y = {}
for (tid, pid) in tp_pairs:
    y[(tid, pid)] = model.addVar(name=f"y_{tid}_{pid}", vtype="B", lb=0, ub=1, obj=0.0)

# Overtime usage vars
ot_vars = {}
for (d, s), info in tech_pool.items():
    ot_vars[(d, s)] = model.addVar(name=f"ot_{d}_{s}", vtype="C", lb=0, ub=info["ot"], obj=0.0)

# Downtime / lateness auxiliaries
downtime_var = {}
lateness_var = {}
for t in tasks:
    if t["downtime"] > 0 and t["mandatory"] and t["type"] in MANDATORY_TYPES:
        downtime_var[t["id"]] = model.addVar(name=f"dt_{t['id']}", vtype="C", lb=0, ub=5.0, obj=0.0)
    if t["lateness"] > 0:
        lateness_var[t["id"]] = model.addVar(name=f"lt_{t['id']}", vtype="C", lb=0, ub=5.0, obj=0.0)

# Co-visit z vars: z[w,p] = 1 if w is not the first work order at its turbine on p
z = {}
turbine_tasks = {}
for t in tasks:
    turbine_tasks.setdefault(t["turbine"], []).append(t["id"])
for (tid, pid) in tp_pairs:
    t = task_by_id[tid]
    if len(turbine_tasks[t["turbine"]]) > 1:
        z[(tid, pid)] = model.addVar(name=f"z_{tid}_{pid}", vtype="B", lb=0, ub=1, obj=0.0)

# Same-turbine anchor credit vars: for preventive w, anchor_cred[w]
anchor_var = {}
for t in tasks:
    if not t["mandatory"] and t["credit"] > 0:
        anchor_var[t["id"]] = model.addVar(name=f"anc_{t['id']}", vtype="B", lb=0, ub=1, obj=0.0)
# pairing vars cvar[w, w', p]
cvar = {}
for w in tasks:
    if not w["mandatory"] and w["credit"] > 0:
        for wp in tasks:
            if wp["mandatory"] and wp["turbine"] == w["turbine"]:
                for p in patterns:
                    if (w["id"], p["id"]) in tp_set and (wp["id"], p["id"]) in tp_set:
                        cvar[(w["id"], wp["id"], p["id"])] = model.addVar(
                            name=f"cv_{w['id']}_{wp['id']}_{p['id']}", vtype="B", lb=0, ub=1, obj=0.0)

# String rule credit vars
rule_cred = {}
for r in string_rules:
    rule_cred[r["id"]] = model.addVar(name=f"rc_{r['id']}", vtype="I", lb=0, ub=r["max"], obj=0.0)
rule_cvar = {}
for r in string_rules:
    anchor = task_by_id[r["anchor"]]
    for w in tasks:
        if w["type"] in r["types"] and turbines[w["turbine"]] == r["string"] and w["id"] != r["anchor"]:
            for p in patterns:
                if (w["id"], p["id"]) in tp_set and (anchor["id"], p["id"]) in tp_set:
                    rule_cvar[(r["id"], w["id"], p["id"])] = model.addVar(
                        name=f"rcv_{r['id']}_{w['id']}_{p['id']}", vtype="B", lb=0, ub=1, obj=0.0)

# ---------------- Constraints ----------------
# 1. Mandatory exactly once / optional at most once
for t in tasks:
    pairs = [pid for (tid, pid) in tp_pairs if tid == t["id"]]
    lhs = quicksum(y[(t["id"], pid)] for pid in pairs)
    if t["mandatory"]:
        model.addCons(lhs == 1, name=f"mand_{t['id']}")
    else:
        model.addCons(lhs <= 1, name=f"opt_{t['id']}")

# 2. One pattern per vessel-day
for v in vessels:
    for d in DAYS:
        pids = [p["id"] for p in patterns if p["vessel"] == v and p["day"] == d]
        if pids:
            model.addCons(quicksum(x[pid] for pid in pids) <= 1, name=f"onepat_{v}_{d}")

# 3. Sailing limits
for v, lim in sail_limits.items():
    pids = [p["id"] for p in patterns if p["vessel"] == v]
    if pids:
        model.addCons(quicksum(x[pid] for pid in pids) <= lim, name=f"sail_{v}")

# 4. Two-day fatigue
for v in vessels:
    for d in DAYS:
        pids = [p["id"] for p in patterns if p["vessel"] == v and p["day"] in (d - 1, d)]
        if pids:
            model.addCons(quicksum(pat_by_id[pid]["fatigue"] * x[pid] for pid in pids)
                          <= vessels[v]["fatigue"], name=f"fat_{v}_{d}")

# 5. Turnaround forbidden consecutive pairs
for i, (prev, nxt) in enumerate(turnaround):
    if prev in pat_by_id and nxt in pat_by_id:
        pp, pn = pat_by_id[prev], pat_by_id[nxt]
        if pp["vessel"] == pn["vessel"] and pn["day"] == pp["day"] + 1:
            model.addCons(x[prev] + x[nxt] <= 1, name=f"turn_{i}")

# 6. Linking y <= x
for (tid, pid) in tp_pairs:
    model.addCons(y[(tid, pid)] <= x[pid], name=f"link_{tid}_{pid}")

# 7. Work-hour capacity with co-visit saving
for p in patterns:
    pids = p["id"]
    terms = []
    for (tid, pid) in tp_pairs:
        if pid != pids:
            continue
        t = task_by_id[tid]
        terms.append(t["hours"] * y[(tid, pid)])
        if (tid, pid) in z:
            terms.append(-COVISIT_SAVING * z[(tid, pid)])
    model.addCons(quicksum(terms) <= p["hours"], name=f"hours_{pids}")

# z constraints: z[w,p] >= (count at turbine on p) - 1 ; z[w,p] <= count - y[w,p] + 1
for (tid, pid) in list(z.keys()):
    t = task_by_id[tid]
    mates = [w for w in turbine_tasks[t["turbine"]]]
    count = quicksum(y[(w, pid)] for w in mates if (w, pid) in y)
    model.addCons(z[(tid, pid)] >= count - 1, name=f"zlo_{tid}_{pid}")
    model.addCons(z[(tid, pid)] <= count - y[(tid, pid)] + 1, name=f"zhi_{tid}_{pid}")

# 8. Technician berths per pattern
for p in patterns:
    pids = p["id"]
    terms = [task_by_id[tid]["techs"] * y[(tid, pid)] for (tid, pid) in tp_pairs if pid == pids]
    if terms:
        model.addCons(quicksum(terms) <= vessels[p["vessel"]]["berths"], name=f"berth_{pids}")

# 9. Deck spares per pattern
for p in patterns:
    pids = p["id"]
    terms = [task_by_id[tid]["spare_units"] * y[(tid, pid)] for (tid, pid) in tp_pairs if pid == pids]
    if terms:
        model.addCons(quicksum(terms) <= vessels[p["vessel"]]["deck"], name=f"deck_{pids}")

# 10. Technician pool per day/skill
for (d, s), info in tech_pool.items():
    terms = []
    for t in tasks:
        if t["skill"] != s:
            continue
        for pid in [p["id"] for p in patterns if p["day"] == d]:
            if (t["id"], pid) in y:
                terms.append(t["techs"] * t["hours"] * y[(t["id"], pid)])
    if terms:
        model.addCons(quicksum(terms) <= info["reg"] + ot_vars[(d, s)], name=f"tech_{d}_{s}")

# 11. Spare inventory per day/type
spare_types = set(t["spare_type"] for t in tasks if t["spare_type"] != "none")
for d in DAYS:
    for st in spare_types:
        avail = spare_inv.get((d, st), 0)
        terms = []
        for t in tasks:
            if t["spare_type"] != st or t["spare_units"] == 0:
                continue
            for pid in [p["id"] for p in patterns if p["day"] == d]:
                if (t["id"], pid) in y:
                    terms.append(t["spare_units"] * y[(t["id"], pid)])
        if terms:
            model.addCons(quicksum(terms) <= avail, name=f"spare_{d}_{st}")

# 12. String daily limits
for s, lim in string_limits.items():
    for d in DAYS:
        mand_terms = []
        total_terms = []
        for t in tasks:
            if turbines[t["turbine"]] != s:
                continue
            for pid in [p["id"] for p in patterns if p["day"] == d]:
                if (t["id"], pid) in y:
                    total_terms.append(y[(t["id"], pid)])
                    if t["mandatory"]:
                        mand_terms.append(y[(t["id"], pid)])
        if mand_terms:
            model.addCons(quicksum(mand_terms) <= lim["mand"], name=f"strm_{s}_{d}")
        if total_terms:
            model.addCons(quicksum(total_terms) <= lim["total"], name=f"strt_{s}_{d}")

# 13. Downtime: dt_var >= d_done - earliest + 1 (only meaningful when done)
for t in tasks:
    if t["id"] in downtime_var:
        ddone = quicksum(pat_by_id[pid]["day"] * y[(t["id"], pid)] for (tid, pid) in tp_pairs if tid == t["id"])
        model.addCons(downtime_var[t["id"]] >= ddone - t["earliest"] + 1, name=f"dtdn_{t['id']}")

# 14. Lateness: lt_var >= d_done - due
for t in tasks:
    if t["id"] in lateness_var:
        ddone = quicksum(pat_by_id[pid]["day"] * y[(t["id"], pid)] for (tid, pid) in tp_pairs if tid == t["id"])
        model.addCons(lateness_var[t["id"]] >= ddone - t["due"], name=f"ltdn_{t['id']}")

# 15. Anchor credit: cvar <= y[w,p], <= y[w',p], >= y[w,p]+y[w',p]-1 ; anchor_var[w] <= sum cvar
for (wid, wpid, pid), cv in cvar.items():
    model.addCons(cv <= y[(wid, pid)], name=f"cva_{wid}_{wpid}_{pid}")
    model.addCons(cv <= y[(wpid, pid)], name=f"cvb_{wid}_{wpid}_{pid}")
    model.addCons(cv >= y[(wid, pid)] + y[(wpid, pid)] - 1, name=f"cvc_{wid}_{wpid}_{pid}")
for w in anchor_var:
    cvsum = quicksum(cv for (wid, wpid, pid), cv in cvar.items() if wid == w)
    model.addCons(anchor_var[w] <= cvsum, name=f"ancsum_{w}")

# 16. String rules: cvar2 <= y[w,p], <= y[anchor,p], >= sum-1 ; rule_cred <= sum cvar2, <= max
for (rid, wid, pid), cv in rule_cvar.items():
    r = [r for r in string_rules if r["id"] == rid][0]
    model.addCons(cv <= y[(wid, pid)], name=f"rca_{rid}_{wid}_{pid}")
    model.addCons(cv <= y[(r["anchor"], pid)], name=f"rcb_{rid}_{wid}_{pid}")
    model.addCons(cv >= y[(wid, pid)] + y[(r["anchor"], pid)] - 1, name=f"rcc_{rid}_{wid}_{pid}")
for r in string_rules:
    cvsum = quicksum(cv for (rid, wid, pid), cv in rule_cvar.items() if rid == r["id"])
    model.addCons(rule_cred[r["id"]] <= cvsum, name=f"rcsum_{r['id']}")

# ---------------- Objective ----------------
obj_terms = []
# Route costs
for p in patterns:
    obj_terms.append(p["cost"] * x[p["id"]])
# Lateness
for t in tasks:
    if t["id"] in lateness_var:
        obj_terms.append(t["lateness"] * lateness_var[t["id"]])
# Downtime
for t in tasks:
    if t["id"] in downtime_var:
        obj_terms.append(t["downtime"] * downtime_var[t["id"]])
# Deferral for omitted optional
for t in tasks:
    if not t["mandatory"] and t["deferral"] > 0:
        done = quicksum(y[(t["id"], pid)] for (tid, pid) in tp_pairs if tid == t["id"])
        obj_terms.append(t["deferral"] * (1 - done))
# Overtime cost
for (d, s), info in tech_pool.items():
    obj_terms.append(info["cost"] * ot_vars[(d, s)])
# Credits (subtracted)
for w, av in anchor_var.items():
    obj_terms.append(-task_by_id[w]["credit"] * av)
for r in string_rules:
    obj_terms.append(-r["credit"] * rule_cred[r["id"]])

model.setObjective(quicksum(obj_terms), sense="minimize")

# ---------------- Solve ----------------
status = "error"
objval = None
try:
    model.optimize()
    status = model.getStatus()
    nsols = model.getNSols()
    if nsols > 0:
        objval = model.getObjVal()
except Exception as e:
    print(f"solve exception: {e}")

# ---------------- Extract solution ----------------
rows = []
sol = None
try:
    sol = model.getBestSol()
except Exception:
    sol = None

selected_patterns = {}
assigned = {}
if sol is not None:
    for p in patterns:
        v = model.getVal(x[p["id"]])
        if v is not None and v > 0.5:
            selected_patterns[p["id"]] = p
    for (tid, pid), var in y.items():
        v = model.getVal(var)
        if v is not None and v > 0.5:
            assigned[tid] = pid

# Route rows
for pid, p in sorted(selected_patterns.items(), key=lambda kv: (kv[1]["day"], kv[0])):
    rows.append(["route", str(p["day"]), p["vessel"], pid, ""])
# Work rows
for tid in sorted(assigned):
    pid = assigned[tid]
    p = pat_by_id[pid]
    rows.append(["work", str(p["day"]), p["vessel"], pid, tid])

sol_path = os.path.join(SUB, "solution.csv")
with open(sol_path, "w", newline="") as f:
    w = csv.writer(f)
    w.writerow(["record_type", "day", "vessel_id", "pattern_id", "task_id"])
    for r in rows:
        w.writerow(r)

# ---------------- Validation ----------------
print(f"status={status} objective={objval} nsols={model.getNSols() if sol is not None else 0} time={model.getSolTime(sol) if sol is not None else -1.00}")
errs = []
# mandatory done exactly once within window
for t in tasks:
    if t["mandatory"]:
        if t["id"] not in assigned:
            errs.append(f"mandatory {t['id']} missing")
            continue
        p = pat_by_id[assigned[t["id"]]]
        if not (t["earliest"] <= p["day"] <= t["latest"]):
            errs.append(f"{t['id']} outside window")
# optional at most once
seen = set()
for tid in assigned:
    if tid in seen:
        errs.append(f"{tid} assigned twice")
    seen.add(tid)
# string limits
for s, lim in string_limits.items():
    for d in DAYS:
        mand = sum(1 for tid, pid in assigned.items() if task_by_id[tid]["mandatory"]
                   and turbines[task_by_id[tid]["turbine"]] == s and pat_by_id[pid]["day"] == d)
        tot = sum(1 for tid, pid in assigned.items()
                  if turbines[task_by_id[tid]["turbine"]] == s and pat_by_id[pid]["day"] == d)
        if mand > lim["mand"]:
            errs.append(f"string {s} day {d} mandatory {mand} > {lim['mand']}")
        if tot > lim["total"]:
            errs.append(f"string {s} day {d} total {tot} > {lim['total']}")
# spares
for d in DAYS:
    for st in spare_types:
        use = sum(task_by_id[tid]["spare_units"] for tid, pid in assigned.items()
                  if task_by_id[tid]["spare_type"] == st and pat_by_id[pid]["day"] == d)
        if use > spare_inv.get((d, st), 0) + 1e-6:
            errs.append(f"spare {st} day {d} use {use} > avail")
# tech pool
for (d, s), info in tech_pool.items():
    use = sum(task_by_id[tid]["techs"] * task_by_id[tid]["hours"] for tid, pid in assigned.items()
              if task_by_id[tid]["skill"] == s and pat_by_id[pid]["day"] == d)
    if use > info["reg"] + info["ot"] + 1e-6:
        errs.append(f"tech {s} day {d} use {use} > pool")
# fatigue / sailing / one-per-day
for v in vessels:
    sd = sum(1 for pid in selected_patterns if pat_by_id[pid]["vessel"] == v)
    if sd > sail_limits.get(v, 99):
        errs.append(f"{v} sailing days {sd}")
    for d in DAYS:
        cnt = sum(1 for pid in selected_patterns if pat_by_id[pid]["vessel"] == v and pat_by_id[pid]["day"] == d)
        if cnt > 1:
            errs.append(f"{v} day {d} multiple patterns")
    for d in DAYS:
        fat = sum(pat_by_id[pid]["fatigue"] for pid in selected_patterns
                  if pat_by_id[pid]["vessel"] == v and pat_by_id[pid]["day"] in (d - 1, d))
        if fat > vessels[v]["fatigue"]:
            errs.append(f"{v} fatigue day {d} {fat}")
for prev, nxt in turnaround:
    if prev in selected_patterns and nxt in selected_patterns:
        errs.append(f"turnaround violation {prev}->{nxt}")
print("validation errors:", errs if errs else "none")
print(f"wrote {sol_path} with {len(rows)} rows")
try:
    model.free()
except Exception:
    pass
sys.exit(0)
